import pytest
from pydantic import ValidationError

from app.schemas.ai import ChatRequest


VALID_CASES = [{'message': 'a'}, {'message': 'aa'}, {'message': 'aaaaa'}, {'message': 'aaaaaaaaaa'}, {'message': 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'}, {'message': 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'}, {'message': ''}, {'message': ''}]
INVALID_CASES = [{'message': ''}, {'message': ''}, {'message': ''}, {'message': ''}, {'message': ''}, {'message': ''}, {'message': ''}, {'message': ''}]


@pytest.mark.parametrize("payload", VALID_CASES)
def test_ai_chat_request_bulk_unit_valid_bulk(payload) -> None:
    model = ChatRequest(**payload)
    assert isinstance(model, ChatRequest)


@pytest.mark.parametrize("payload", INVALID_CASES)
def test_ai_chat_request_bulk_unit_invalid_bulk(payload) -> None:
    with pytest.raises(ValidationError):
        ChatRequest(**payload)
